SELECT
    type_name AS name,
    SUM(type_count) AS value
FROM stat_sw_type_cache


        AND company_code IN
        #{c}


        AND county_code = #{countyCode}


        AND park_code = #{parkCode}


        AND yq_type = #{yqType}


        AND is_scqy = #{isScqy}


GROUP BY type_name
ORDER BY value DESC
